const routes=[['/','Start','home'],['/varumarken/','Varumärken','brands'],['/produkter/','Produkter','products'],['/inspiration/','Inspiration','inspiration'],['/om-oss/','Om oss','about'],['/kontakt/','Kontakt','contact']];
const page=document.body.dataset.page||'home';
const header=`<header class="site-header"><a href="/" aria-label="Food InWest startsida"><img class="brand-logo" src="https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/foodinwest-logo.png" alt="Food InWest"></a><nav class="nav" aria-label="Huvudnavigation">${routes.slice(1).map(([url,label,id])=>`<a href="${url}" ${page===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="portal-link" href="/kundportal/">Kundportal</a><button class="menu-button" aria-expanded="false">Meny</button></header>`;
const footer=`<footer class="footer"><div><img src="https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/foodinwest-logo.png" alt="Food InWest"><p>Noggrant utvalda produkter och varumärken för handel, restaurang och matupplevelser. Denna webbversion är en designprototyp.</p></div><div class="footer-links"><a href="/varumarken/">Varumärken</a><a href="/produkter/">Produkter</a><a href="/kontakt/">Kontakt</a><a href="/kundportal/">Kundportal</a></div></footer>`;
const pageHero=(kicker,title,text)=>`<section class="page-hero"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${text}</p></div></section>`;
const home=`<main><section class="hero"><div class="hero-content"><div class="eyebrow">Food InWest</div><h1>Noggrant utvalt.<span>Aldrig slentrian.</span></h1><div class="hero-rule"></div><p>Bättre mat. Större upplevelser.</p><div class="actions"><a class="button" href="/produkter/">Upptäck sortimentet <span>→</span></a><a class="text-link" href="/varumarken/">Våra varumärken</a></div></div></section><section class="feature-grid"><a class="feature-card brands" href="/varumarken/"><div class="eyebrow">Varumärken</div><h2>Världens bästa matvarumärken på en plats.</h2><span class="text-link">Utforska varumärken →</span></a><a class="feature-card products" href="/produkter/"><div class="eyebrow">Produkter</div><h2>Noggrant utvalda produkter för en rikare vardag.</h2><span class="text-link">Se vårt sortiment →</span></a><a class="feature-card inspiration" href="/inspiration/"><div class="eyebrow">Inspiration</div><h2>Mat som inspirerar och förenar.</h2><span class="text-link">Läs mer →</span></a></section></main>`;
const brands=`<main>${pageHero('Våra varumärken','Personlighet på varje hylla.','Ett koncentrerat urval där varje varumärke får ta plats med sin egen berättelse, smak och karaktär.')}<section class="section"><div class="section-head"><div><div class="eyebrow">Utvalt sortiment</div><h2>Varumärken att upptäcka</h2></div><p class="section-copy">Utforska ett urval av de varumärken som syns i vår godkända produktbild. Fullständigt sortiment och verifierad produktinformation ansluts i nästa steg.</p></div><div class="boxed-grid"><a class="box" style="--image:url('https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/hero-products.png');--position:4% center"><small>Dryck</small><h3>Luscombe</h3><p>Karaktärsfull dryck i ett uttryck som får synas.</p></a><a class="box" style="--image:url('https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/hero-products.png');--position:48% center"><small>Snacks</small><h3>Fairfields Farm</h3><p>Krispigt, direkt och tydligt presenterat.</p></a><a class="box" style="--image:url('https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/hero-products.png');--position:63% center"><small>Smaksättare</small><h3>Gran Luchito</h3><p>Smak som tar plats både i köket och på hyllan.</p></a><a class="box" style="--image:url('https://foodinwest-premium.rcbdywtqkh.chatgpt.site/assets/hero-products.png');--position:79% center"><small>Såser</small><h3>Stokes</h3><p>Ett klassiskt uttryck i den premiumgröna världen.</p></a></div></section></main>`;
const products=`<main>${pageHero('Sortiment','Produkter valda med omsorg.','En första interaktiv katalog för framtida B2B-beställning. Produktuppgifterna nedan är demonstrationsinnehåll.')}<section class="section"><div class="product-tools"><input id="search" type="search" placeholder="Sök produkt eller varumärke" aria-label="Sök produkter"><select id="category" aria-label="Filtrera kategori"><option value="">Alla kategorier</option><option>Dryck</option><option>Snacks</option><option>Såser</option><option>Delikatesser</option></select></div><div class="product-list" id="product-list"></div></section></main>`;
const inspiration=`<main>${pageHero('Inspiration','Smak börjar med en idé.','Serveringsidéer, producentberättelser och miljöer där produkterna får skapa något större.')}<section class="feature-grid"><article class="feature-card products"><div class="eyebrow">Servering</div><h2>En enkel råvara. En större upplevelse.</h2><span class="text-link">Läs berättelsen →</span></article><article class="feature-card inspiration"><div class="eyebrow">Vid bordet</div><h2>Mat som blir bättre när den delas.</h2><span class="text-link">Se inspiration →</span></article><article class="feature-card brands"><div class="eyebrow">Urval</div><h2>Produkterna bakom smakerna.</h2><span class="text-link">Utforska →</span></article></section></main>`;
const about=`<main>${pageHero('Om Food InWest','Urval före utfyllnad.','Food InWest ska upplevas som en kunnig, personlig och krävande kurator av matvarumärken.')}<section class="story-layout"><div class="story-image" role="img" aria-label="Food InWest i en professionell matmiljö"></div><div class="story-text"><div class="eyebrow">Vår princip</div><h2>Noggrant utvalt. Aldrig slentrian.</h2><p>Webbplatsen är byggd kring samma idé: färre men tydligare val, starka bilder och plats för varje varumärke att uttrycka sin karaktär.</p><p>Den här första versionen skapar grunden för en framtida B2B-portal med kundpriser, lagerstatus och beställning.</p><a class="text-link" href="/kontakt/">Prata med oss →</a></div></section></main>`;
const contact=`<main>${pageHero('Kontakt','Låt oss prata bättre mat.','Kontakta Food InWest om sortiment, återförsäljning eller ett framtida kundkonto.')}<section class="section"><form class="form-grid" id="contact-form"><div class="field"><label for="name">Namn</label><input id="name" required></div><div class="field"><label for="company">Företag</label><input id="company"></div><div class="field"><label for="email">E-post</label><input id="email" type="email" required></div><div class="field"><label for="phone">Telefon</label><input id="phone" type="tel"></div><div class="field full"><label for="message">Meddelande</label><textarea id="message" required></textarea></div><div class="field full"><button class="button" type="submit">Skicka förfrågan →</button><p class="note">Designprototyp: formuläret skickar ännu ingen information.</p></div></form></section></main>`;
const portal=`<main>${pageHero('Kundportal','För framtidens beställningar.','Ett visuellt förhandsläge. Inloggning, kundpriser och orderläggning kopplas på i en senare fas.')}<section class="section"><div class="portal-panel"><span class="status-chip">Förhandsläge</span><h2>Logga in</h2><div class="field"><label for="portal-email">E-post</label><input id="portal-email" type="email"></div><div class="field"><label for="portal-password">Lösenord</label><input id="portal-password" type="password"></div><button class="button" type="button">Logga in</button><p class="note">Ingen autentisering är aktiverad i prototypen.</p><a class="text-link" href="/kontakt/">Ansök om kundkonto →</a></div></section></main>`;
const views={home,brands,products,inspiration,about,contact,portal};
document.body.innerHTML=header+(views[page]||home)+footer;
document.querySelector('.menu-button')?.addEventListener('click',e=>{const h=document.querySelector('.site-header');h.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',h.classList.contains('open'))});
const demoProducts=[['Luscombe','Sicilian Lemonade','Dryck'],['Fairfields Farm','Sea Salt Crisps','Snacks'],['Gran Luchito','Smoky Chipotle','Såser'],['Stokes','Real Mayonnaise','Såser'],['Plain & Simple','Aceitunas Verdes','Delikatesser']];
function drawProducts(){const target=document.querySelector('#product-list');if(!target)return;const q=(document.querySelector('#search').value||'').toLowerCase();const c=document.querySelector('#category').value;target.innerHTML=demoProducts.filter(x=>(!q||x.join(' ').toLowerCase().includes(q))&&(!c||x[2]===c)).map(x=>`<article class="product-card"><div><div class="brand">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]} · Visningsprodukt</p></div><a href="/kontakt/">Fråga om produkten →</a></article>`).join('')||'<p>Inga produkter matchar filtret.</p>'}
document.querySelector('#search')?.addEventListener('input',drawProducts);document.querySelector('#category')?.addEventListener('change',drawProducts);drawProducts();
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();alert('Tack! Formuläret är en prototyp och skickar ännu ingen information.')});
